/* From Uiverse.io by Webdevava - Tags: button */
.__UIV_SCOPE__ button {
  background: #111;
  border: none;
  padding: 10px 14px;
  border-radius: 6px;
  color: #fff;
  font-size: 30px;
}

.__UIV_SCOPE__ button:hover {
  border: 3px solid #fff;
  transform: rotate3d(0, 1, 0.5, 360deg);
  transition: 1.5s;
}
